  "findings": [
    {
      "ref": "[D537]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, going by what parents report.",
      "stance": "neutral",
      "quote": "Restrict access to online game features and hide games and content in PlayStation™Store based on your child's age."
    },
    {
      "ref": "[D537]",
      "area": "money",
      "claim": "The app pushes in-app purchases and subscription traps.",
      "stance": "risk",
      "quote": "Set the maximum amount of money that each child can spend per month in PlayStation™Store."
    },
    {
      "ref": "[D537]",
      "area": "data",
      "claim": "It collects user data and may share it with third parties for ads.",
      "stance": "risk",
      "quote": "The password is set to [0000] in the default settings. If you select (Settings) > (System Settings) > [Restore Default Settings], you can reset the password to [0000]."
    },
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with the child, and it is on by default.",
      "stance": "risk",
      "quote": "The default setting is \"Block\" meaning chat/message is restricted."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports that user-generated media and chat can expose children to inappropriate material.",
      "stance": "risk",
      "quote": "This control blocks a Sub Account from using text chat, voice chat, video chat, and other messaging features, from communicating directly with other users in games or via system software features."
    },
    {
      "ref": "[D537]",
      "area": "developer_record",
      "claim": "The developer has faced regulatory scrutiny and fines for privacy violations.",
      "stance": "risk",
      "quote": "In the Americas, PlayStation system parental controls correspond to the ESRB rating assigned to each game; they do not correspond to the DEJUS rating."
    }
  ]
